const k=(type,key)=>({k:`crew.type.${type}.${key}`});
export const missions=ROWS.map(([id,type,level,placeId,lat,lon,zh,en,zhs,cc,region,cat,z,ox,oy,src])=>{
 const T=crewTypes[type],checklist=[1,2,3].map(i=>k(type,'chk'+i)),objectives=[1,2,3].map(i=>k(type,'obj'+i));
 const place=placeId?{lat,lon,zh,en,zhs,cc,region,cat}:null;
 return {id,type,domain:T.domain,vehicle:T.vehicle,level,placeId,place,sat:{z,ox,oy},title:k(type,'title'),description:k(type,'brief'),briefing:[k(type,'tip')],objectives,checklist,deskSteps:[...checklist,...objectives],
  durationMinutes:{basic:8,advanced:12,expert:15}[level],roles:['pilot','navigator','observer','coordinator'],
  sourceUrls:[...(src?[src]:[]),...(place?[`https://www.openstreetmap.org/?mlat=${lat}&mlon=${lon}#map=15/${lat}/${lon}`]:[]),...SOURCES[T.domain]],fictional:true,geographicContextOnly:true};
});
export const scenariosById=Object.fromEntries(missions.map(m=>[m.id,m]));
